<?php
use App\Http\Controllers\{AffiliateController, ChatController, DashboardController, OrderController, PaymentController, ProgressController, WalletController, WorkerController}; use Illuminate\Support\Facades\Route;
Route::get('/', fn()=>redirect()->route('dashboard'));
Route::middleware(['auth','verified'])->group(function(){ Route::get('/dashboard', DashboardController::class)->name('dashboard'); Route::resource('orders', OrderController::class)->only(['index','create','store','show']); Route::post('/orders/{order}/progress', [ProgressController::class,'store'])->name('orders.progress.store'); Route::post('/orders/{order}/invoice', [PaymentController::class,'invoice'])->name('orders.invoice'); Route::post('/payments/{payment}/verify', [PaymentController::class,'verify'])->middleware('role:owner|admin')->name('payments.verify'); Route::get('/workers', [WorkerController::class,'index'])->middleware('role:owner|admin')->name('workers.index'); Route::get('/wallet', [WalletController::class,'index'])->name('wallet.index'); Route::post('/wallet/withdraw', [WalletController::class,'withdraw'])->name('wallet.withdraw'); Route::get('/affiliate', [AffiliateController::class,'index'])->name('affiliate.index'); Route::get('/chat/{room}', [ChatController::class,'room'])->name('chat.room'); Route::post('/chat/{room}', [ChatController::class,'store'])->name('chat.store'); });
Route::post('/webhooks/midtrans', [PaymentController::class,'webhook'])->withoutMiddleware([\Illuminate\Foundation\Http\Middleware\VerifyCsrfToken::class]);
require __DIR__.'/auth.php';
